// 視聴ルールの内容。
type WatchRuleInput struct {
	// 1〜200 文字
	Name       string                  `json:"name"`
	Enabled    bool                    `json:"enabled"`
	Conditions *ProgramConditionsInput `json:"conditions"`
}

// Web Push の購読 (設計書 6.2)。端末とブラウザごとに 1 つある。
